(r, big) => {
  const n = big ? 100000 : r.int(1, 16), pOpen = big ? r.pick([0.3, 0.6]) : 0.4;
  let s = "", d = 0, needOperand = true;
  while (s.length + d < n || needOperand) {
    if (needOperand) {
      if (s.length + d < n - 3 && r.bool(pOpen)) { s += "("; d++; }
      else { s += r.int(0, 9); needOperand = false; }
    } else if (d > 0 && r.bool(0.4)) { s += ")"; d--; }
    else { s += r.pick(["+", "-", "*", "/"]); needOperand = true; }
  }
  return [s + ")".repeat(d)];
}

