function bracketDepth(s: string): number {
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    let d = 0;
    for (let j = 0; j <= i; j++) {
      if (s[j] === "(") d++;
      else if (s[j] === ")") d--;
    }
    best = Math.max(best, d);
  }
  return best;
}

